'use strict';

/* The wholesale sample responses Codex builds against
 * (docs/wholesale-v1-fixtures.json) must be what the API really answers.
 * They are generated by tools/wholesale-fixtures.js from the same view code;
 * this fails when the code moved and the file was not regenerated.
 *
 * Run: node --test tests/wholesale-fixtures.test.js
 * Fix: node tools/wholesale-fixtures.js
 */

const { test } = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const FX = require('../tools/wholesale-fixtures');
const W = require('../tools/lib/wholesale');

test('committed fixtures match the code', () => {
  assert.strictEqual(fs.readFileSync(FX.file, 'utf8'), FX.out,
    'docs/wholesale-v1-fixtures.json is stale: run node tools/wholesale-fixtures.js');
});

test('every status has a sample, and each sample is in that status', () => {
  const fx = FX.build();
  for (const s of W.STATUSES) assert.strictEqual(fx.requests[s] && fx.requests[s].status, s, s);
  assert.strictEqual(fx.requests.reapproval_required.reapproval_required, true);
});

test('no shop-only field is in any sample', () => {
  assert.ok(!/blank_price|product_id|unit_override/.test(FX.out));
});

test('the signed sample verifies with the documented algorithm', () => {
  const s = FX.build().signed_webhook;
  assert.ok(W.verifySignature(s.secret, s.header, s.raw_body, s.signed_at_unix * 1000));
});
